def help_for(ids):
    template = match_template(ids)
    intro = HELP.get(template["key"], "") if template else ""
    if MAIN_SIGNATURE <= frozenset(ids):
        intro = "PowerManagerII сообщает о состоянии подключённого ИБП. Начните с F6: откроется содержимое открытой вкладки. Три вкладки: Состояние ИБП, Текущие измерения, График измерений. Control+Tab, Control+Shift+Tab и стрелки на заголовках перемещают фокус. Enter или пробел открывает вкладку в фокусе. До этого данные не меняются. Tab или F6 переводит к содержимому открытой вкладки; стрелки читают строки; F5 обновляет данные. Escape возвращает в исходную программу. F10 открывает меню: Система, Вид, Управление ИБП, Помощь. Дополнительная панель команд и элементов доступна в исходном окне по NVDA+Alt+F1.\n"
    return title_for(ids) + "\n\n" + intro + "\n" + COMMON
